from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import mm
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
products=[
('conversation-starter','Conversation Starter Playbook','Start better conversations','A practical guide to opening conversations naturally and keeping them flowing.',[
('01 · Start with context','The easiest opener is connected to something real: a shared setting, a detail in a profile, a recent event or a genuine question. “Hey” is not wrong, but adding context gives the other person something to respond to. Avoid pretending to share interests you do not have.'),
('02 · Openers you can adapt','“You mentioned you love live music—what was the best show you have been to?”  |  “That café looks interesting. Is it worth visiting?”  |  “I noticed you are learning photography. What do you enjoy shooting most?” Adapt the wording to the person and situation; do not send a line that feels unlike you.'),
('03 · Keep the exchange balanced','Answer the question you ask. If you ask about a favourite film, share yours too. A conversation feels natural when both people contribute stories, opinions and questions. Avoid firing off several questions in a row.'),
('04 · Follow-up prompts','If they mention a trip: “What was the highlight?” If they mention a hobby: “How did you get into it?” If they share a strong opinion: “What made you see it that way?” Follow the thread they choose rather than forcing your prepared topic.'),
('05 · When the chat slows','Try one gentle change of direction, share a small story or let the conversation rest. Silence is not an emergency. If replies stay short or they do not respond, give space rather than sending repeated follow-ups.'),
('06 · Your practice plan','Choose one opener that sounds like you. Remove exaggerated compliments and pressure. Make it specific, friendly and easy to answer. After sending it, put your phone down and continue your day.')]),
('flirting-mastery','Flirting Mastery Guide','Playful, not pushy','A grounded guide to warm, confident and respectful flirting.',[
('01 · The foundation is mutual interest','Flirting should feel enjoyable for both people. Look for reciprocal effort: they ask questions, build on jokes, initiate sometimes and seem comfortable. One smile or one emoji is not proof of attraction.'),
('02 · Use playful observations','A light observation can create warmth: “You have very strong opinions about coffee—I respect the commitment.” Keep humour kind. Avoid insults disguised as teasing, negging, sexual pressure or jokes about sensitive traits.'),
('03 · Give specific compliments','Notice choices and qualities: “You explain things in a really engaging way” or “That colour looks great on you.” Be sincere, proportionate and comfortable with a simple thank-you.'),
('04 · Read the response','If they respond warmly and continue the exchange, you can keep the tone playful. If they change the subject, give minimal replies or seem uncomfortable, ease off. Consent and comfort matter more than a clever line.'),
('05 · Make an invitation clearly','When conversation is going well, try: “I have enjoyed talking with you. Would you like to get coffee sometime?” A clear invitation is easier to answer than hints. Accept yes, no or uncertainty gracefully.'),
('06 · Keep your own centre','Confidence is not acting unavailable or trying to create jealousy. Keep your routines, friendships and interests. You can show interest without making another person responsible for your self-worth.')]),
('texting-psychology','Texting Psychology Guide','Text with clarity','Understand texting habits, pacing and expectations without overthinking.',[
('01 · A message is not a mind reader','A delayed reply can mean work, family, low phone use, stress or many other things. Online status, read receipts and typing indicators are incomplete information. Avoid turning one data point into a story about your worth.'),
('02 · Build a healthy rhythm','Reply when you reasonably can. You do not need to mirror every minute or wait deliberately to appear busy. A sustainable rhythm is one that fits both people’s lives and leaves room for offline time.'),
('03 · Ask questions that invite detail','Instead of “wyd?” every day, try “What was the best part of your day?” or “Did that project turn out how you hoped?” Ask because you are interested, not to test whether someone cares.'),
('04 · Handle uncertainty directly','If a pattern is bothering you, describe it without accusation: “I enjoy talking with you. We seem to have different texting rhythms—what works for you?” Listen to the answer and decide whether the arrangement works for you too.'),
('05 · Avoid common traps','Do not send repeated messages to force a reply, monitor someone’s activity, use jealousy tactics or treat response time as a loyalty test. If you need reassurance, ask respectfully and also practise self-soothing.'),
('06 · A simple reset','Mute notifications for a short period, do one offline activity and return to the conversation when you feel settled. If communication consistently feels one-sided, consider a calm conversation about expectations.')]),
('relationship-red-flags','Relationship Red Flags Guide','Notice the patterns','A reflection guide for boundaries, respect and relationship wellbeing.',[
('01 · Pattern over isolated moment','Everyone makes mistakes. Pay attention to repeated behaviour, the impact it has and whether the person takes responsibility and changes. You do not need to label someone to decide a behaviour is not acceptable to you.'),
('02 · Respect and autonomy','Warning signs can include monitoring your phone, controlling who you see, pressuring you to share passwords, isolating you from support or making ordinary independence feel unsafe. Healthy relationships allow privacy and separate friendships.'),
('03 · Communication and accountability','Repeated humiliation, threats, blame-shifting, deliberate intimidation or punishment through silence can undermine emotional safety. A sincere repair includes listening, accountability and changed behaviour—not only apologies.'),
('04 · Boundaries you can use','“I am not comfortable sharing my passwords.”  |  “I want to discuss this without insults.”  |  “I need time to think; I will talk when we are both calm.” A boundary describes what you will do to protect your wellbeing.'),
('05 · Check your support network','Talk to a trusted friend, family member or qualified professional if you feel confused, isolated or afraid. If you are in immediate danger, contact local emergency services. Do not confront someone alone if doing so could increase risk.'),
('06 · Reflection checklist','Can I disagree safely? Do my boundaries matter? Do I feel free to see friends and make choices? Are apologies followed by change? Do I feel more like myself in this relationship? Your answers can help clarify what support or next step you need.')]),
('30-day-confidence','30-Day Confidence Challenge','Small steps, real progress','A month of manageable exercises for self-trust and everyday confidence.',[
('WEEK 1 · Build self-trust','Day 1: List three moments you handled something difficult. Day 2: Complete one small task you have delayed. Day 3: Write down a strength supported by evidence. Day 4: Take a ten-minute walk without scrolling. Day 5: Practise introducing yourself aloud. Day 6: Say a kind, specific thing to yourself. Day 7: Review what felt easier.'),
('WEEK 2 · Practise connection','Day 8: Start a low-pressure conversation. Day 9: Ask one curious follow-up question. Day 10: Give a genuine compliment. Day 11: Share an opinion respectfully. Day 12: Send a message you have been postponing. Day 13: Listen without planning your reply. Day 14: Reflect on one interaction that went well.'),
('WEEK 3 · Strengthen boundaries','Day 15: Notice one situation where you say yes automatically. Day 16: Practise “Let me think about it.” Day 17: Decline one nonessential request politely if needed. Day 18: Spend time on a personal interest. Day 19: Reduce one comparison trigger. Day 20: Ask clearly for something reasonable. Day 21: Review where your time goes.'),
('WEEK 4 · Take visible action','Day 22: Wear something that feels like you. Day 23: Try a new route or activity. Day 24: Ask for feedback on a skill. Day 25: Complete a small fitness or learning goal. Day 26: Make a plan and follow through. Day 27: Celebrate progress without comparing. Day 28: Do one thing that feels mildly uncomfortable but safe.'),
('DAYS 29–30 · Keep what works','Day 29: Write a note to your future self describing what changed. Day 30: Choose three habits to continue next month. Confidence is built through repeated evidence that you can act, learn, recover and keep promises to yourself.'),
('Weekly reflection','What did I try? What felt uncomfortable? What did I learn? What will I repeat? Rate confidence from 1–10 as a personal reflection, not a performance score. Progress may be uneven; adjust the challenge to your circumstances.')])]
styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='Cover',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=27,leading=31,textColor=colors.HexColor('#171512'),alignment=TA_CENTER,spaceAfter=14));styles.add(ParagraphStyle(name='Sub',parent=styles['Normal'],fontSize=12,leading=18,textColor=colors.HexColor('#716b62'),alignment=TA_CENTER,spaceAfter=12));styles.add(ParagraphStyle(name='H',parent=styles['Heading2'],fontName='Helvetica-Bold',fontSize=15,leading=19,textColor=colors.HexColor('#B83A32'),spaceBefore=12,spaceAfter=7));styles.add(ParagraphStyle(name='Body2',parent=styles['BodyText'],fontSize=10.5,leading=16,textColor=colors.HexColor('#292621'),spaceAfter=10))
for slug,title,tagline,desc,sections in products:
    path=ROOT/'public'/'products'/f'{slug}.pdf'
    doc=SimpleDocTemplate(str(path),pagesize=A4,rightMargin=22*mm,leftMargin=22*mm,topMargin=22*mm,bottomMargin=20*mm,title=title,author='TEMPLY')
    story=[Spacer(1,42*mm),Paragraph('TEMPLY · DIGITAL PLAYBOOK',styles['Sub']),Paragraph(title,styles['Cover']),Paragraph(tagline,styles['Sub']),Spacer(1,12*mm),Paragraph(desc,styles['Body2']),Spacer(1,45*mm),Paragraph('A practical guide · Read at your own pace',styles['Sub']),PageBreak(),Paragraph('A NOTE BEFORE YOU BEGIN',styles['H']),Paragraph('Use these ideas as starting points, not scripts you must follow. Be yourself, respect other people’s choices and adapt every example to the context. No guide can guarantee a particular response or relationship outcome.',styles['Body2'])]
    for h,b in sections: story += [Paragraph(h,styles['H']),Paragraph(b.replace('&','&amp;'),styles['Body2'])]
    story += [Spacer(1,12),Paragraph('TEMPLY · Better words. Better connections.',styles['Sub'])]
    def footer(canvas,doc):
        canvas.saveState();canvas.setStrokeColor(colors.HexColor('#E8DFD1'));canvas.line(22*mm,15*mm,188*mm,15*mm);canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#716B62'));canvas.drawString(22*mm,10*mm,'TEMPLY · PERSONAL USE');canvas.drawRightString(188*mm,10*mm,str(doc.page));canvas.restoreState()
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
print('Created',len(products),'PDF guides')
